 const main='<div id="beespoke-deliverability-full"><main id="main-content"><div class="d-hero"><p class="breadcrumbs"><a href="'+pre+'/resources/">'+esc(p.resources)+'</a> / '+esc(p.breadcrumb)+'</p><h1>'+esc(p.h1)+'</h1><p class="answer">'+esc(p.answer)+'</p><div class="d-actions"><a class="d-button" href="#d-symptoms" data-delivery-jump="d-symptoms">'+esc(p.read)+'</a><a href="#d-register" data-delivery-jump="d-register" data-open-register>'+esc(p.registerLink)+'</a></div><p class="d-small">'+esc(p.author)+' <a href="'+pre+'/about/noah-levy/">Noah Levy</a> · '+esc(p.updated)+'</p><p class="d-small">'+esc(p.fiction)+'</p></div><details class="mobile-toc"><summary>'+esc(p.contents)+'</summary><nav aria-label="'+esc(p.contents)+'">'+nav+'</nav></details><div class="d-layout"><aside class="d-rail"><p>'+esc(p.contents)+'</p><nav aria-label="'+esc(p.contents)+'">'+nav+'</nav></aside><article>'+p.sections.map(s=>'<section id="'+s.id+'"><h2>'+esc(s.title)+'</h2>'+s.blocks.map(b=>render(b,p,pre)).join('')+'</section>').join('')+'<section id="d-faq"><h2>'+esc(p.faqTitle)+'</h2>'+p.faqs.map(([q,a])=>'<details class="d-faq"><summary>'+esc(q)+'</summary><p>'+esc(a)+'</p></details>').join('')+'</section><section id="d-sources"><h2>'+esc(p.sourcesTitle)+'</h2><p>'+esc(p.sourceIntro)+'</p><ol>'+sources.map(([n,u],i)=>'<li><a href="'+esc(u)+'" rel="noopener">'+esc(n)+'</a> — '+esc(p.sourceNotes[i])+'</li>').join('')+'</ol></section></article></div></main><script type="application/json" data-deliverability-config>'+safe(p.ui)+'</script></div>';
